def choose_move(observation):
    w, h = observation['grid_width'], observation['grid_height']
    x, y = observation['self_position']
    opp_x, opp_y = observation['opponent_position']
    resources = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    remaining = observation.get('remaining_resource_count', 0)

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def move_towards(target):
        dx = dy = 0
        if target:
            if target[0] > x: dx = 1
            elif target[0] < x: dx = -1
            if target[1] > y: dy = 1
            elif target[1] < y: dy = -1
        # Prefer horizontal movement
        if dx != 0 and (x + dx, y) not in obstacles and 0 <= x + dx < w:
            return [dx, 0]
        if dy != 0 and (x, y + dy) not in obstacles and 0 <= y + dy < h:
            return [0, dy]
        # Try perpendicular move if forward blocked
        if dx != 0 and (x, y + 1) not in obstacles and y + 1 < h:
            return [0, 1]
        if dx != 0 and (x, y - 1) not in obstacles and y - 1 >= 0:
            return [0, -1]
        if dy != 0 and (x + 1, y) not in obstacles and x + 1 < w:
            return [1, 0]
        if dy != 0 and (x - 1, y) not in obstacles and x - 1 >= 0:
            return [-1, 0]
        return [0, 0]

    # Find nearest resource
    nearest_resource = None
    min_dist = None
    for res in resources:
        d = dist((x, y), res)
        if min_dist is None or d < min_dist:
            min_dist = d
            nearest_resource = res

    # If resources left, move towards nearest
    if remaining > 0 and nearest_resource:
        return move_towards(nearest_resource)

    # Else, move towards opponent to block or pursue
    return move_towards((opp_x, opp_y))
